    {
      "requirement_id": "SDLC-FR-0301",
      "anchors": ["tsa-s03", "tsa-s04", "tsa-s05", "tsa-s06", "tsa-s08", "tsa-s10", "tsa-s13"],
      "how_satisfied": "The Audit Export Handler validates the requested date range and consults a deny-by-default Export Authorization Policy before reading any data. Unauthorized requests receive a refusal. Authorized requests receive a downloadable file streamed from a consistent snapshot of the append-only Audit Store. The file contains every event whose timestamp is within the range, ordered by timestamp with sequence as the tie-breaker, so the export holds exactly the range's events in time order.",
      "constraints": [
        "The set of users or roles authorized to export is not defined by the Requirement, so the authorization policy's grant rule is left open and denies by default.",
        "The file format is not defined beyond being downloadable; the line-per-record text serialization is a design choice, not an obligation."
      ],
      "gaps": [
        "Who is authorized to export is undefined, so no identity can be granted export until that decision is made.",
        "Range boundary semantics (inclusive or exclusive ends, time zone of the chosen dates) are undefined, and exact range membership depends on them."
      ]
    },
    {
      "requirement_id": "SDLC-FR-0302",
      "anchors": ["tsa-s03", "tsa-s04", "tsa-s05", "tsa-s06", "tsa-s08", "tsa-s10", "tsa-s12", "tsa-s13"],
      "how_satisfied": "All administrative actions, including every service configuration change, run through a single Administrative Command Boundary. The boundary writes exactly one audit event, holding the action, the authenticated acting identity and the server time, in the same database transaction as the change. Events are written to an append-only table that has no modify or delete path in the service and no update or delete privilege for the runtime role. Only allowlisted non-secret attributes are captured, so events never contain secrets.",
      "constraints": [
        "Administrative actions are defined only as including service configuration changes; any further administrative action types must be registered once identified.",
        "Audit events never contain secrets, which is enforced through allowlist capture."
      ],
      "gaps": [
        "Which actions beyond service configuration changes count as administrative is undefined; the registry covers configuration changes and any other operations routed through the boundary."
      ]
    }
  ],
  "assumptions": [
    "The service already authenticates callers and can supply an authenticated identity for both administrative actions and export requests.",
    "Service configuration is stored in a transactional database that can also hold the audit table, so the change and its audit event can be written atomically.",
    "The service's database supports per-table privilege restriction and consistent read snapshots.",
    "Audit volume over typical export ranges is small enough for synchronous streaming export to be practical."
  ],
  "risks": [
    {
      "detail": "An administrative code path that bypasses the Administrative Command Boundary would go unaudited, breaking the every-action guarantee. This is mitigated by mandatory registration and refusal of unregistered operations, but it depends on all paths being routed during migration.",
      "impact": "HIGH"
    },
    {
      "detail": "Fail-closed recording means a database or audit-write failure blocks administrative actions, reducing the availability of administration.",
      "impact": "MEDIUM"
    },
    {
      "detail": "With no defined retention, the audit table grows without bound, which may affect storage and export performance over time.",
      "impact": "MEDIUM"
    },
    {
      "detail": "Very large export ranges may hold database connections for a long time while streaming.",
      "impact": "LOW"
    },
    {
      "detail": "Until the authorized-exporter decision is made, the deny-by-default policy refuses every export, so the export capability is unusable in practice.",
      "impact": "MEDIUM"
    }
  ],
  "open_architecture_questions": [
    "Should a privileged, out-of-service archival mechanism be designed now, or deferred until a retention decision exists?",
    "Is a maximum export range or size limit needed to keep synchronous streaming exports within operational limits, or would an asynchronous export path be warranted?"
